options.customCss:
:root {
	--font-family: 'Open Sans', sans-serif;
	--font-weight-normal: 400;
	--font-weight-bold: 600;
	--font-size-body: 12px;
	--font-size-label: 14px;
	--font-size-test-notice: 12px;
	--font-size-input: 14px;
	--font-size-header: 20px;
	--font-size-paragraph: 14px;
	--font-size-link: 12px;
	--font-size-error: 12px;
	--font-size-html-h1: 28px;
	--font-size-html-h2: 20px;
	--font-size-html-h3: 16px;
	--font-size-html-h4: 14px;
	--font-size-html-h5: 12px;
	--font-size-html-h6: 10px;
	--font-size-subheader: 14px;

	/* Cores Dark Mode Premium */
	--color-background: #0d0e12;           /* Fundo da tela ultra escuro */
	--color-card-bg: #16171d;              /* Fundo do card grafite */
	--color-card-border: #242631;          /* Borda sutil do card */
	--color-card-shadow: rgba(255, 109, 90, 0.15); /* Sombra neon coral */

	--color-header: #ffffff;               /* Título branco */
	--color-header-subtext: #8e94a5;       /* Subtítulo cinza claro */
	--color-label: #c5cbd8;                /* Labels visíveis no escuro */

	--color-focus-border: #634dff;         /* Roxo elétrico no foco */
	--color-submit-btn-bg: #ff6d5a;        /* Botão Coral ativo */
	--color-submit-btn-text: #ffffff;

	--color-error: #ff4a5a;
	--color-required: #ff6d5a;
	--color-link: #8e94a5;
	--color-html-link: #ff6d5a;

	--color-test-notice-text: #ffb03a;
	--color-test-notice-bg: #221c13;
	--color-test-notice-border: #3d301d;

	/* Radii & Spacing */
	--border-radius-card: 12px;
	--border-radius-input: 8px;
	--padding-container-top: 24px;
	--padding-card: 32px;
	--margin-bottom-card: 16px;
	--padding-form-input: 14px;

	/* Dimensions */
	--container-width: 448px;
	--submit-btn-height: 52px;
	--checkbox-size: 18px;

	/* Box Shadows */
	--box-shadow-card: 0px 8px 32px 0px rgba(0, 0, 0, 0.5), 0px 0px 24px 0px var(--color-card-shadow);
}

/* Reset & Base Setup */
* {
	box-sizing: border-box;
	margin: 0;
	padding: 0;
}

body {
	font-family: var(--font-family);
	background-color: var(--color-background);
	color: #e2e5ec;
	font-size: var(--font-size-body);
	font-weight: var(--font-weight-normal);
	display: flex;
	justify-content: center;
	align-items: center;
	min-height: 100vh;
	padding: var(--padding-container-top) 16px;
	-webkit-font-smoothing: antialiased;
}

/* Form Container / Card */
.form-card {
	width: 100%;
	max-width: var(--container-width);
	background-color: var(--color-card-bg);
	border: 1px solid var(--color-card-border);
	border-radius: var(--border-radius-card);
	box-shadow: var(--box-shadow-card);
	padding: var(--padding-card);
}

/* Header Section */
.form-header {
	margin-bottom: 28px;
}

.form-header h1 {
	color: var(--color-header);
	font-size: var(--font-size-header);
	font-weight: var(--font-weight-bold);
	margin-bottom: 8px;
	letter-spacing: -0.5px;
}

.form-header p {
	color: var(--color-header-subtext);
	font-size: var(--font-size-subheader);
}

/* Notice Banner */
.test-notice {
	background-color: var(--color-test-notice-bg);
	border: 1px solid var(--color-test-notice-border);
	color: var(--color-test-notice-text);
	border-radius: var(--border-radius-input);
	padding: 12px 16px;
	font-size: var(--font-size-test-notice);
	margin-bottom: 24px;
}

/* Form Groups */
.form-group {
	margin-bottom: 22px;
	display: flex;
	flex-direction: column;
}

/* Labels */
.form-group label {
	color: var(--color-label);
	font-size: var(--font-size-label);
	font-weight: var(--font-weight-bold);
	margin-bottom: 10px;
	letter-spacing: 0.2px;
}

.form-group label.required::after {
	content: " *";
	color: var(--color-required);
}

/* Inputs, Textareas & Selects (Texto e Placeholder Escuros) */
.form-control {
	width: 100%;
	height: 46px;
	padding: var(--padding-form-input);
	font-family: var(--font-family);
	font-size: var(--font-size-input);

	color: #16171d;                 /* Texto digitado escuro */
	background-color: #ffffff;      /* Fundo branco para contraste */
	border: 1px solid #dbdfe7;      /* Borda clara padrão */

	border-radius: var(--border-radius-input);
	transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
	outline: none;
}

textarea.form-control {
	height: auto;
	min-height: 110px;
	resize: vertical;
}

/* Cor do Placeholder Ajustada para Escuro */
.form-control::placeholder {
	color: #71747A;                 /* Cinza escuro legível */
	opacity: 0.7;                   /* Opacidade sutil */
}

/* Estado de Foco (Efeito Glow) */
.form-control:focus {
	border-color: var(--color-focus-border);
	background-color: #ffffff;
	box-shadow: 0px 0px 14px 0px rgba(99, 77, 255, 0.25);
}

/* Estado de Erro */
.form-group.has-error .form-control {
	border-color: var(--color-error);
	box-shadow: 0px 0px 14px 0px rgba(255, 74, 90, 0.15);
}

.error-message {
	color: var(--color-error);
	font-size: var(--font-size-error);
	margin-top: 8px;
	font-weight: var(--font-weight-bold);
}

/* Checkbox Customizado */
.form-checkbox {
	display: flex;
	flex-direction: row;
	align-items: center;
	cursor: pointer;
	gap: 12px;
	margin-bottom: 24px;
}

.form-checkbox input[type="checkbox"] {
	width: var(--checkbox-size);
	height: var(--checkbox-size);
	accent-color: var(--color-submit-btn-bg);
	cursor: pointer;
}

.form-checkbox span {
	color: var(--color-label);
	font-size: var(--font-size-paragraph);
	user-select: none;
}

/* Botão Principal com Sombra de Alta Intensidade */
.btn-submit {
	width: 100%;
	height: var(--submit-btn-height);
	background-color: var(--color-submit-btn-bg);
	color: var(--color-submit-btn-text);
	font-family: var(--font-family);
	font-size: var(--font-size-input);
	font-weight: var(--font-weight-bold);
	border: none;
	border-radius: var(--border-radius-input);
	cursor: pointer;
	box-shadow: 0px 4px 18px 0px rgba(255, 109, 90, 0.35);
	transition: all 0.2s ease;
}

.btn-submit:hover {
	transform: translateY(-1px);
	box-shadow: 0px 6px 24px 0px rgba(255, 109, 90, 0.5);
	opacity: 0.95;
}

.btn-submit:active {
	transform: translateY(1px);
	box-shadow: 0px 2px 8px 0px rgba(255, 109, 90, 0.3);
}

/* Footer Links */
.form-footer-links {
	display: flex;
	justify-content: space-between;
	align-items: center;
	margin-top: 20px;
}

.form-link {
	color: var(--color-link);
	font-size: var(--font-size-link);
	text-decoration: none;
	transition: color 0.2s ease;
}

.form-link:hover {
	color: var(--color-html-link);
	text-shadow: 0px 0px 8px rgba(255, 109, 90, 0.4);
}

